const IDB={db:null,open(){return new Promise((ok,no)=>{if(this.db)return ok(this.db);try{const r=indexedDB.open('tasyir_img',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>{this.db=r.result;ok(this.db)};r.onerror=()=>no(r.error)}catch(e){no(e)}})},
 async tx(mode,fn){const d=await this.open();return new Promise((ok,no)=>{const t=d.transaction('images',mode),r=fn(t.objectStore('images'));t.oncomplete=()=>ok(r&&r.result);t.onerror=()=>no(t.error)})},
 put(k,v){return this.tx('readwrite',s=>s.put(v,k))},get(k){return this.tx('readonly',s=>s.get(k))},del(k){return this.tx('readwrite',s=>s.delete(k))}};
function imgComp(f){return new Promise((ok,no)=>{const r=new FileReader();r.onerror=no;r.onload=()=>{const im=new Image();im.onerror=no;im.onload=()=>{const k=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);ok(c.toDataURL('image/jpeg',.75))};im.src=r.result};r.readAsDataURL(f)})}
