const TN=()=>({p1:L('تجزئة','Détail','Retail'),p2:L('نصف جملة','Demi-gros','Semi-wholesale'),p3:L('جملة','Gros','Wholesale')});
function tp(p,tr,q){if(!ST().tiers)return p.price;let k=tr;if(k==='p1'&&p.tierMin>0&&q>=p.tierMin&&p.p3>0)k='p3';return(k==='p2'?p.p2:k==='p3'?p.p3:p.price)||p.price}
function reprice(){cart.forEach(l=>{if(l.man)return;const p=db.products.find(x=>x.id===l.pid);if(p)l.price=tp(p,l.tier||tier,l.qty)})}
