function payInfo(tot){const r=P(pr.value),e=document.getElementById('pinf');if(!e)return;e.innerHTML=r>=tot?`<span class="grn">${t('chg')}: ${M(r-tot)}</span>`:`<span class="red">${t('debt')}: ${M(tot-r)}</span>`}
function doSell(paidC){if(busy)return;busy=true;let ok=0;try{
 for(const l of cart){const p=db.products.find(x=>x.id===l.pid);if(!p||l.qty<=0||(!ST().allowNeg&&p.stock<l.qty)){alert(t('nostock')+l.name);return}}
 const sub_=subT(),dc=Math.min(sub_,cdisc),total=sub_-dc,paid=Math.min(total,Math.max(0,paidC)),debt=total-paid,pc=document.getElementById('pcu');if(pc&&pc.value)cu=pc.value;
 if(debt>0&&!cu){alert(t('needc'));return}
 const s={id:uid(),no:'INV-'+String(++db.seq).padStart(5,'0'),d:new Date().toISOString(),day:day(),lines:cart.map(l=>({pid:l.pid,name:l.name,qty:l.qty,price:l.price,cost:l.cost,total:Math.round(l.price*l.qty),tier:l.man?'m':(l.tier||tier)})),sub:sub_,disc:dc,total,paid,debt,cust:cu||null,tier,note:cnote};
 s.lines.forEach(l=>{const p=db.products.find(x=>x.id===l.pid);p.stock=r3(p.stock-l.qty)});
 if(debt>0)db.ledger.push({id:uid(),c:cu,t:'debt',a:debt,d:s.d,ref:s.no});
 db.sales.push(s);saveNow();cart=[];cu='';cdisc=0;cnote='';tier='p1';ok=1;ov.innerHTML='';receipt(s)}finally{busy=false;if(ok)R()}}
