 const two=(a,b_,bd)=>{font(bd);c.textAlign=rtl?'right':'left';c.fillText(a,rtl?W-8:8,y+F);c.textAlign=rtl?'left':'right';c.fillText(b_,rtl?8:W-8,y+F);y+=lh};
 const sep=()=>{c.fillRect(0,y+lh/2,W,2);y+=lh};
 ctr(sh.name||db.shop||t('app'),1);if(sh.address)ctr(sh.address);if(sh.phone)ctr(sh.phone);if(ST().printer.head)ctr(ST().printer.head);sep();
 two(s.no,new Date(s.d).toLocaleDateString(LC()));if(cs)ctr(cs.name);sep();
 s.lines.forEach(l=>{wrap(l.name+(l.tier&&l.tier!=='p1'&&ST().tiers?' ['+(l.tier==='m'?'*':TN()[l.tier])+']':'')).forEach(x=>{font(0);c.textAlign=rtl?'right':'left';c.fillText(x,rtl?W-8:8,y+F);y+=lh});two(l.qty+' × '+M(l.price),M(l.total))});sep();
 if(s.disc)two(t('disc'),'-'+M(s.disc));two(t('total'),M(s.total),1);two(t('paid'),M(s.paid));if(s.debt)two(t('debt'),M(s.debt));
