const PAL=['#0f766e','#14b8a6','#f59e0b','#ef4444','#6366f1','#84cc16','#ec4899','#64748b'];
function svgLine(a){if(a.length<2)return svgBars(a);const w=320,h=110,mx=Math.max(1,...a.map(x=>x.v)),pt=a.map((x,i)=>[8+i*(w-16)/(a.length-1),h-14-(x.v/mx)*(h-28)]);
 return`<svg viewBox="0 0 ${w} ${h}" width="100%"><path d="M${pt.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#0f766e" stroke-width="2.5"/>${pt.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.5" fill="#0f766e"/>`).join('')}<text x="4" y="${h-2}" font-size="9" fill="#94a3b8">${esc(a[0].l)}</text><text x="${w-4}" y="${h-2}" font-size="9" fill="#94a3b8" text-anchor="end">${esc(a[a.length-1].l)}</text></svg>`}
function svgBars(a){const w=320,h=110,mx=Math.max(1,...a.map(x=>x.v)),bw=(w-10)/Math.max(1,a.length);
 return`<svg viewBox="0 0 ${w} ${h}" width="100%">${a.map((x,i)=>{const bh=(x.v/mx)*(h-28);return`<rect x="${5+i*bw+1}" y="${h-14-bh}" width="${Math.max(1,bw-2)}" height="${bh}" rx="2" fill="#14b8a6"/><text x="${5+i*bw+bw/2}" y="${h-3}" font-size="${a.length>14?6:9}" fill="#94a3b8" text-anchor="middle">${esc(x.l)}</text>`}).join('')}</svg>`}
function svgPie(a){const tot=a.reduce((s,x)=>s+x.v,0)||1;let ang=-Math.PI/2;const R_=50;
 const sl=a.map((x,i)=>{const f=x.v/tot,e=ang+f*2*Math.PI,l=f>.5?1:0,d=f>=.999?`M60,10 A50,50 0 1 1 59.9,10 Z`:`M60,60 L${60+R_*Math.cos(ang)},${60+R_*Math.sin(ang)} A${R_},${R_} 0 ${l} 1 ${60+R_*Math.cos(e)},${60+R_*Math.sin(e)} Z`;ang=e;return`<path d="${d}" fill="${PAL[i%8]}"/>`}).join('');
 return`<div style="display:flex;gap:10px;align-items:center"><svg viewBox="0 0 120 120" width="120">${sl}</svg><div style="font-size:12px">${a.map((x,i)=>`<div><span style="color:${PAL[i%8]}">■</span> ${esc(x.l)} ${Math.round(x.v/tot*100)}%</div>`).join('')}</div></div>`}
