 const ap=db.products.filter(x=>!x.arch),vc=ap.reduce((s,x)=>s+Math.round(Math.max(0,x.stock)*x.cost),0),vs=ap.reduce((s,x)=>s+Math.round(Math.max(0,x.stock)*x.price),0);
