 <div class="g">${card(L('المبيعات','Ventes','Sales'),c.rev,p.rev)}<div class="card"><div class="k">${L('الفواتير / المتوسط','Factures / moyenne','Invoices / avg')}</div><div class="v">${c.cnt} / ${M(c.avg)}</div>${dl(c.cnt,p.cnt)}</div>${card(L('الربح الإجمالي','Profit brut','Gross profit'),c.gp,p.gp)}${card(L('المصاريف والرواتب','Dépenses & salaires','Expenses & payroll'),c.ex,p.ex)}${card(L('الربح الصافي','Profit net','Net profit'),c.net,p.net)}<div class="card"><div class="k">${L('الهامش','Marge','Margin')}</div><div class="v">${c.rev?Math.round(c.gp/c.rev*100):0}%</div></div></div>
