function dues(w,upto){const r=[],s=pd_(w.start||iso(new Date())),e=pd_(upto);
 if(w.cycle==='w'){const d=new Date(s);while(d.getDay()!==(+w.dow||0))d.setDate(d.getDate()+1);for(;d<=e&&r.length<400;d.setDate(d.getDate()+7))r.push(iso(d))}
 else{let y=s.getFullYear(),mo=s.getMonth();while(r.length<400){const dim=new Date(y,mo+1,0).getDate(),dt=new Date(y,mo,Math.min(+w.dom||1,dim),12);if(dt>e)break;if(dt>=s)r.push(iso(dt));mo++;if(mo>11){mo=0;y++}}}return r}
function payPeriod(w,date){const key=w.id+':'+date;if(w.paid.some(x=>x.k===key)||db.expenses.some(e=>e.periodKey===key))return false;
 const gross=Math.max(0,w.salary+(w.adj||0)),ded=Math.min(w.adv||0,gross),net=gross-ded;w.adv=(w.adv||0)-ded;w.adj=0;
 if(net>0)db.expenses.push({id:uid(),n:L('راتب: ','Salaire : ','Salary: ')+w.name,a:net,day:date,d:pd_(date).toISOString(),cat:'salary',workerId:w.id,periodKey:key});
 w.paid.push({k:key,day:date,gross,ded,net});return true}
function pending(w){const td=iso(new Date());return dues(w,td).filter(d=>!w.paid.some(x=>x.k===w.id+':'+d))}
function runPayroll(){let n=0;try{db.workers.forEach(w=>{if(!w.active)return;if(w.auto!==false)pending(w).forEach(d=>{if(payPeriod(w,d))n++})});if(n){save();if(tab==='wrk'||tab==='exp')R();toast('[ok] '+n+' '+L('راتب/رواتب تم خصمها','salaire(s) enregistré(s)','payroll entries added'))}}catch(e){onErr(e.message)}}
