let capUnk='',capLim=50,capQ='';
function capT(){let c=0,s=0,u=0;db.capDraft.forEach(l=>{const p=db.products.find(x=>x.id===l.pid);if(!p)return;c+=Math.round(l.q*p.cost);s+=Math.round(l.q*p.price);u+=l.q});return{c,s,u,n:db.capDraft.length}}
VIEWS.cap=function(){return`<div class="card sup"><div class="bg" id="capt"></div></div><div class="bar" style="margin-bottom:8px"><button class="b" style="flex:1" onclick="scan(capScan,1)">${ic('camera')} ${L('مسح متواصل','Scan continu','Continuous scan')}</button><button class="b s" onclick="capSave()">${ic('save')}</button><button class="b s" onclick="capSess()">${ic('folder')}</button></div>
 <input placeholder="${t('search')}" oninput="capQ=this.value;capFind(this.value)" autocomplete="off"><div id="capf"></div><div id="capu"></div><div id="capl"></div>
 <div class="bar" style="margin-top:8px"><button class="b s" style="flex:1" onclick="capCsv()">CSV</button><button class="b r" style="flex:1" onclick="capApply()">${L('تطبيق كجرد','Appliquer en inventaire','Apply as stocktake')}</button><button class="b s" onclick="if(confirm(t('cf'))){db.capDraft.length=0;save();R()}">${ic('eraser')}</button></div>`};
function capUp(){const T_=capT(),e=document.getElementById('capt');if(!e)return;e.innerHTML=`<div><span class="k">${L('الأصناف / القطع','Articles / pièces','Items / units')}</span><br><b>${T_.n} / ${r3(T_.u)}</b></div><div><span class="k">${L('رأس المال','Capital','Capital')}</span><br><b>${M(T_.c)}</b></div><div><span class="k">${L('قيمة البيع','Valeur de vente','Sales value')}</span><br><b>${M(T_.s)}</b></div><div><span class="k">${L('الربح المتوقع','Profit prévu','Expected profit')}</span><br><b class="grn">${M(T_.s-T_.c)}</b></div>`;
 document.getElementById('capu').innerHTML=capUnk?`<div class="card" style="background:#fef3c7;color:#92400e">${t('nof')}: ${esc(capUnk)} <button class="b sm" onclick="pForm();document.getElementById('f1').value='${esc(capUnk)}';bcPrev();capUnk=''">${ic('plus')}</button></div>`:'';
 const q=capQ?nz(capQ):'';const a=db.capDraft.filter(l=>{if(!q)return true;const p=db.products.find(x=>x.id===l.pid);return p&&mt(p,capQ)});
 document.getElementById('capl').innerHTML=a.slice(0,capLim).map(l=>{const p=db.products.find(x=>x.id===l.pid);if(!p)return'';return`<div class="row">${th(p)}<div style="flex:1"><b>${esc(p.name)}</b><div class="k">${t('cost')}: ${M(p.cost)} · ${t('price')}: ${M(p.price)}</div><div class="k">${M(Math.round(l.q*p.cost))}</div></div><input type="number" step="any" style="width:70px" value="${l.q}" onchange="capSet('${l.pid}',N(this.value))"><button class="b sm r" onclick="capSet('${l.pid}',0)">${ic('x')}</button></div>`}).join('')+(a.length>capLim?`<button class="b s" style="width:100%" onclick="capLim+=50;capUp()">${t('more')} (${a.length-capLim})</button>`:'')}
function capSet(pid,q){const i=db.capDraft.findIndex(l=>l.pid===pid);if(i<0)return;if(q<=0)db.capDraft.splice(i,1);else db.capDraft[i].q=q;save();capUp()}
function capScan(c){const p=findP(c);if(!p){capUnk=c;capUp();return[0,t('nof')+': '+c]}let l=db.capDraft.find(x=>x.pid===p.id);if(l)l.q=r3(l.q+1);else{l={pid:p.id,q:1};db.capDraft.unshift(l)}capUnk='';save();capUp();return[1,p.name+' ×'+l.q]}
function capFind(v){const b=document.getElementById('capf');v=v.trim();if(!v){b.innerHTML='';capUp();return}b.innerHTML=db.products.filter(p=>!p.arch&&mt(p,v)).slice(0,6).map(p=>`<div class="row" onclick="capScan('${esc(p.bc||'P:'+p.id)}')"><span style="flex:1">${esc(p.name)}</span><span>${M(p.cost)}</span></div>`).join('');capUp()}
function capSave(){form(L('حفظ الجلسة','Enregistrer la session','Save session'),[[t('name'),0,'text',day()]],v=>{db.capSessions.push({id:uid(),name:v[0].trim()||day(),d:new Date().toISOString(),lines:JSON.parse(JSON.stringify(db.capDraft))});save()})}
function capSess(){sheet(`<h3>${L('الجلسات المحفوظة','Sessions','Saved sessions')}</h3>`+(db.capSessions.map(s=>`<div class="row"><span style="flex:1">${esc(s.name)} <span class="k">(${s.lines.length})</span></span><button class="b sm" onclick="capLoad('${s.id}')">${ic('play')}</button><button class="b sm r" onclick="db.capSessions=db.capSessions.filter(x=>x.id!=='${s.id}');save();capSess()">${ic('x')}</button></div>`).join('')||`<div class="k">${t('none')}</div>`))}
function capLoad(id){const s=db.capSessions.find(x=>x.id===id);if(!s)return;if(db.capDraft.length&&!confirm(t('cf')))return;db.capDraft.length=0;s.lines.forEach(l=>db.capDraft.push({...l}));save();ov.innerHTML='';R()}
function capCsv(){const r=[['name','barcode','purchase','price','qty','cost_total']].concat(db.capDraft.map(l=>{const p=db.products.find(x=>x.id===l.pid)||{};return[p.name,p.bc,p.cost/100,p.price/100,l.q,l.q*p.cost/100]}));dlFile('capital-'+day()+'.csv',['\ufeff'+r.map(x=>x.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n')],'text/csv')}
function capApply(){if(!db.capDraft.length)return;if(!confirm(L('سيتم استبدال كميات هذه المنتجات في المخزون بالكميات المعدودة. متابعة؟','Les stocks de ces produits seront remplacés par les quantités comptées. Continuer ?','Stock of these products will be REPLACED by the counted quantities. Continue?')))return;
 try{localStorage.setItem(K+'_safety',JSON.stringify(db))}catch(e){}db.capDraft.forEach(l=>{const p=db.products.find(x=>x.id===l.pid);if(p)p.stock=l.q});save();toast('[ok] '+L('تم تطبيق الجرد','Inventaire appliqué','Stocktake applied'))}
