const busy_=on=>{const e=document.getElementById('busy');if(e)e.classList.toggle('on',on)};
async function bk(){busy_(true);try{const o=JSON.parse(JSON.stringify(db)),im={};for(const l of db.supLedger)for(const k of(l.imgs||[])){if(im[k])continue;try{const v=await IDB.get(k);if(v)im[k]=v}catch(e){}}o._images=im;ST().lastBackup=Date.now();save();dlFile('shop-backup-'+day()+'.json',[JSON.stringify(o)],'application/json')}catch(e){onErr(e.message)}finally{busy_(false)}}
function rs_(f){if(!f)return;const r=new FileReader();r.onload=async()=>{try{busy_(true);const d=JSON.parse(r.result);if(!Array.isArray(d.products)||!Array.isArray(d.sales)||!Array.isArray(d.ledger))throw 0;if(!confirm(t('cf')))return;
 try{localStorage.setItem(K+'_safety',JSON.stringify(db))}catch(e){}const im=d._images||{};delete d._images;
 for(const k of Object.keys(im)){try{await IDB.put(k,im[k])}catch(e){}}
 db=Object.assign({lang:db.lang,shop:'',customers:[],expenses:[],seq:0},d);ensure();db.v=2;saveNow();applyTheme();R()}catch(e){alert(t('bad'))}finally{busy_(false)}};r.readAsText(f)}
